package main

import (
	"bufio"
	"container/heap"
	"fmt"
	"os"
)

type item struct {
	cost int64
	node int
}

type queue []item

func (q queue) Len() int            { return len(q) }
func (q queue) Less(i, j int) bool  { return q[i].cost < q[j].cost }
func (q queue) Swap(i, j int)       { q[i], q[j] = q[j], q[i] }
func (q *queue) Push(x interface{}) { *q = append(*q, x.(item)) }
func (q *queue) Pop() interface{} {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]
	return last
}

type edge struct {
	target int
	price  int64
}

func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	var tests int
	fmt.Fscan(in, &tests)
	for ; tests > 0; tests-- {
		var n, m int
		fmt.Fscan(in, &n, &m)
		graph := make([][]edge, n+1)
		for i := 0; i < m; i++ {
			var from, to int
			var price int64
			fmt.Fscan(in, &from, &to, &price)
			graph[from] = append(graph[from], edge{to, price})
		}
		best := make([]int64, n+1)
		for i := range best {
			best[i] = -1
		}
		best[1] = 0
		pending := &queue{{0, 1}}
		for pending.Len() > 0 {
			top := heap.Pop(pending).(item)
			for _, e := range graph[top.node] {
				if best[e.target] == -1 {
					best[e.target] = top.cost + e.price
					heap.Push(pending, item{best[e.target], e.target})
				}
			}
		}
		fmt.Fprintln(out, best[n])
	}
}

